import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import { LEGS, LEG_SPECS, PAW_RADIUS, TAIL_SEGMENTS, type CatPose, type LegName } from "@/lib/cat/gait";

/**
 * The Beopity black cat, built procedurally so it needs no model download and
 * can be regenerated by editing this file. Proportions follow the approved
 * mascot: a large kitten head, pale mint eyes, warm inner ears and a hooked tail.
 * The hierarchy is a simple rig: body → head/legs/tail, legs as hip → knee → paw.
 */
export type CatModel = {
  root: THREE.Group;
  body: THREE.Group;
  torso: THREE.Mesh;
  head: THREE.Group;
  legs: Record<LegName, { hip: THREE.Group; knee: THREE.Group; paw: THREE.Group }>;
  paws: Record<LegName, THREE.Group>;
  tail: THREE.Bone[];
  ears: THREE.Group[];
  eyes: { group: THREE.Group; pupil: THREE.Mesh }[];
  fur: THREE.ShaderMaterial;
  dispose: () => void;
};

export const CAT_COLORS = {
  fur: "#2b211c",
  furShade: "#100c0a",
  rim: "#c08a62",
  innerEar: "#c98d78",
  nose: "#8e5a4b",
  eye: "#dcefbf",
  pupil: "#16201f",
  outline: "#0b0807",
  whisker: "#d9d1c2",
};

// Skinning chunks are inert on ordinary meshes and deform the rigged tail.
const vertexShader = /* glsl */ `
  #include <common>
  #include <skinning_pars_vertex>
  varying vec3 vNormal;
  varying vec3 vObject;
  void main() {
    #include <skinbase_vertex>
    #include <beginnormal_vertex>
    #include <skinnormal_vertex>
    #include <begin_vertex>
    #include <skinning_vertex>
    vObject = position;
    vNormal = normalize(normalMatrix * objectNormal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(transformed, 1.0);
  }
`;

// Ink line: back faces pushed out along the normal give an even outline.
const outlineVertex = /* glsl */ `
  #include <common>
  #include <skinning_pars_vertex>
  uniform float uThickness;
  void main() {
    #include <skinbase_vertex>
    #include <beginnormal_vertex>
    #include <skinnormal_vertex>
    #include <begin_vertex>
    #include <skinning_vertex>
    transformed += normalize(objectNormal) * uThickness;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(transformed, 1.0);
  }
`;
const outlineFragment = /* glsl */ `
  uniform vec3 uColor;
  void main() {
    gl_FragColor = vec4(uColor, 1.0);
    #include <colorspace_fragment>
  }
`;

// Two-tone cel shading, painterly grain and a warm rim that reads on charcoal.
const fragmentShader = /* glsl */ `
  uniform vec3 uBase;
  uniform vec3 uShade;
  uniform vec3 uRim;
  uniform vec3 uLight;
  uniform float uRimStrength;
  uniform float uGrain;
  varying vec3 vNormal;
  varying vec3 vObject;
  float hash(vec3 p) {
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
  }
  float noise(vec3 x) {
    vec3 i = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(mix(hash(i), hash(i + vec3(1, 0, 0)), f.x), mix(hash(i + vec3(0, 1, 0)), hash(i + vec3(1, 1, 0)), f.x), f.y),
      mix(mix(hash(i + vec3(0, 0, 1)), hash(i + vec3(1, 0, 1)), f.x), mix(hash(i + vec3(0, 1, 1)), hash(i + vec3(1, 1, 1)), f.x), f.y),
      f.z);
  }
  void main() {
    vec3 n = normalize(vNormal);
    float light = dot(n, normalize(uLight));
    float tone = smoothstep(-0.2, 0.08, light) * 0.55 + smoothstep(0.42, 0.6, light) * 0.45;
    float strokes = noise(vObject * vec3(34.0, 82.0, 34.0)) * 0.6 + noise(vObject * 11.0) * 0.4;
    vec3 color = mix(uShade, uBase, tone);
    color *= 1.0 + (strokes - 0.5) * uGrain;
    float fresnel = 1.0 - max(n.z, 0.0);
    float rim = smoothstep(0.5, 0.86, fresnel) * (0.55 + 0.45 * strokes);
    color = mix(color, uRim, rim * uRimStrength);
    gl_FragColor = vec4(color, 1.0);
    #include <colorspace_fragment>
  }
`;

function toonMaterial(base: string, shade: string, rimStrength: number, grain = 0.55) {
  return new THREE.ShaderMaterial({
    vertexShader,
    fragmentShader,
    uniforms: {
      uBase: { value: new THREE.Color(base) },
      uShade: { value: new THREE.Color(shade) },
      uRim: { value: new THREE.Color(CAT_COLORS.rim) },
      uLight: { value: new THREE.Vector3(-0.45, 0.8, 0.55) },
      uRimStrength: { value: rimStrength },
      uGrain: { value: grain },
    },
  });
}

const HEAD_Y = 0.2;
const TAIL_STEP = 0.075;

/** Small cones for fur tufts: [x, y, z, direction x, direction y, direction z]. */
function tufts(spec: number[][], radius: number, length: number) {
  return spec.map(([x, y, z, dx, dy, dz]) => {
    const geometry = new THREE.ConeGeometry(radius, length, 7, 1);
    const direction = new THREE.Vector3(dx, dy, dz).normalize();
    geometry.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction));
    geometry.translate(x + direction.x * length * 0.3, y + direction.y * length * 0.3, z + direction.z * length * 0.3);
    return geometry;
  });
}

function ellipsoid(radius: number, scale: [number, number, number], position: [number, number, number], detail = 1) {
  const geometry = new THREE.SphereGeometry(radius, Math.round(26 * detail), Math.round(18 * detail));
  geometry.scale(...scale);
  geometry.translate(...position);
  return geometry;
}

export function createCatModel(): CatModel {
  const fur = toonMaterial(CAT_COLORS.fur, CAT_COLORS.furShade, 0.85);
  const innerEar = toonMaterial(CAT_COLORS.innerEar, "#7d4d43", 0.15, 0.35);
  const nose = toonMaterial(CAT_COLORS.nose, "#4b2c25", 0.1, 0.2);
  const outline = new THREE.ShaderMaterial({
    vertexShader: outlineVertex,
    fragmentShader: outlineFragment,
    side: THREE.BackSide,
    uniforms: { uColor: { value: new THREE.Color(CAT_COLORS.outline) }, uThickness: { value: 0.011 } },
  });
  const eye = new THREE.MeshBasicMaterial({ color: CAT_COLORS.eye });
  const pupil = new THREE.MeshBasicMaterial({ color: CAT_COLORS.pupil });
  const glint = new THREE.MeshBasicMaterial({ color: "#ffffff" });
  const whisker = new THREE.LineBasicMaterial({ color: CAT_COLORS.whisker, transparent: true, opacity: 0.55 });

  const inked = (geometry: THREE.BufferGeometry, material: THREE.Material = fur) => {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.add(new THREE.Mesh(geometry, outline));
    return mesh;
  };

  const root = new THREE.Group();
  root.name = "Beopity cat";
  const body = new THREE.Group();
  root.add(body);

  const torsoParts = [
    ellipsoid(1, [0.225, 0.215, 0.37], [0, 0, 0]),
    ellipsoid(0.225, [1, 1.06, 1], [0, 0.03, 0.19]),
    ellipsoid(0.24, [1.02, 1, 1], [0, 0.03, -0.21]),
    // Soft chest ruff, as in the mascot's fluffy front.
    ellipsoid(0.16, [1.2, 1.25, 0.8], [0, 0.02, 0.33]),
  ];
  const torsoGeometry = mergeGeometries(torsoParts)!;
  torsoParts.forEach((part) => part.dispose());
  const torso = inked(torsoGeometry, fur);
  body.add(torso);

  const head = new THREE.Group();
  head.position.set(0, HEAD_Y, 0.36);
  body.add(head);
  const headParts = [
    ellipsoid(0.262, [1.06, 0.95, 0.95], [0, 0.1, 0.08], 1.2),
    ellipsoid(0.14, [1.15, 0.85, 0.9], [0.14, 0.02, 0.15]),
    ellipsoid(0.14, [1.15, 0.85, 0.9], [-0.14, 0.02, 0.15]),
    ellipsoid(0.09, [1.3, 0.78, 0.85], [0, 0.012, 0.29]),
    ellipsoid(0.065, [1.1, 0.7, 0.9], [0, -0.04, 0.26]),
    // Fluffy cheeks, after the hand-painted fur in the artwork.
    ...tufts([[0.26, 0.0, 0.12, 1, -0.35, 0.1], [0.25, -0.06, 0.1, 1, -0.9, 0.1], [-0.26, 0.0, 0.12, -1, -0.35, 0.1], [-0.25, -0.06, 0.1, -1, -0.9, 0.1]], 0.04, 0.085),
  ];
  const headGeometry = mergeGeometries(headParts)!;
  headParts.forEach((part) => part.dispose());
  head.add(inked(headGeometry, fur));
  const noseMesh = new THREE.Mesh(ellipsoid(0.026, [1.35, 0.8, 0.8], [0, 0.058, 0.36]), nose);
  head.add(noseMesh);

  const eyes: CatModel["eyes"] = [];
  for (const side of [1, -1]) {
    const group = new THREE.Group();
    group.position.set(0.102 * side, 0.135, 0.292);
    group.rotation.set(-0.08, 0.32 * side, 0);
    const ball = new THREE.Mesh(ellipsoid(0.08, [1, 1.05, 0.55], [0, 0, 0]), eye);
    const iris = new THREE.Mesh(ellipsoid(0.043, [0.9, 1.08, 0.5], [0, 0, 0.034]), pupil);
    const shine = new THREE.Mesh(ellipsoid(0.014, [1, 1, 0.5], [0.019, 0.028, 0.054]), glint);
    iris.add(shine);
    group.add(ball, iris);
    head.add(group);
    eyes.push({ group, pupil: iris });
  }

  const ears: THREE.Group[] = [];
  const earGeometry = new THREE.ConeGeometry(0.1, 0.22, 16, 1);
  earGeometry.scale(1, 1, 0.55);
  const innerGeometry = new THREE.ConeGeometry(0.066, 0.15, 16, 1);
  innerGeometry.scale(1, 1, 0.4);
  for (const side of [1, -1]) {
    const ear = new THREE.Group();
    ear.position.set(0.145 * side, 0.3, 0.05);
    ear.rotation.set(-0.12, 0, -0.36 * side);
    const outer = inked(earGeometry, fur);
    outer.position.y = 0.08;
    const inner = new THREE.Mesh(innerGeometry, innerEar);
    inner.position.set(0, 0.065, 0.028);
    ear.add(outer, inner);
    head.add(ear);
    ears.push(ear);
  }

  const whiskerPoints: number[] = [];
  for (const side of [1, -1]) for (const [lift, spread] of [[0.02, 0.06], [0, 0], [-0.02, -0.06]]) {
    whiskerPoints.push(0.15 * side, 0.01 + lift, 0.25, 0.36 * side, 0.02 + lift * 3 + spread, 0.24);
  }
  const whiskerGeometry = new THREE.BufferGeometry();
  whiskerGeometry.setAttribute("position", new THREE.Float32BufferAttribute(whiskerPoints, 3));
  head.add(new THREE.LineSegments(whiskerGeometry, whisker));

  const legs = {} as CatModel["legs"];
  const paws = {} as CatModel["paws"];
  const shapes = new Map<string, THREE.BufferGeometry>();
  const capsule = (radius: number, length: number) => {
    const key = `${radius}:${length}`;
    if (!shapes.has(key)) {
      const geometry = new THREE.CapsuleGeometry(radius, length, 6, 14);
      geometry.translate(0, -length / 2, 0);
      shapes.set(key, geometry);
    }
    return shapes.get(key)!;
  };
  const pawGeometry = ellipsoid(PAW_RADIUS, [1.05, 0.85, 1.3], [0, -0.006, 0.018]);
  for (const name of LEGS) {
    const spec = LEG_SPECS[name];
    const fore = name.startsWith("fore");
    const hip = new THREE.Group();
    hip.position.set(...spec.hip);
    const upper = inked(capsule(fore ? 0.068 : 0.085, spec.upper));
    const knee = new THREE.Group();
    knee.position.y = -spec.upper;
    const lower = inked(capsule(fore ? 0.058 : 0.06, spec.lower));
    const paw = new THREE.Group();
    paw.position.y = -spec.lower;
    paw.add(inked(pawGeometry));
    knee.add(lower, paw);
    hip.add(upper, knee);
    body.add(hip);
    legs[name] = { hip, knee, paw };
    paws[name] = paw;
  }

  // The tail is one continuous skinned tube on a chain of bones.
  const tail: THREE.Bone[] = [];
  const tailLength = TAIL_SEGMENTS * TAIL_STEP;
  const tailGeometry = new THREE.CylinderGeometry(1, 1, tailLength, 12, TAIL_SEGMENTS * 4, false);
  tailGeometry.rotateX(Math.PI / 2);
  tailGeometry.translate(0, 0, -tailLength / 2);
  const position = tailGeometry.getAttribute("position");
  const skinIndex: number[] = [], skinWeight: number[] = [];
  for (let i = 0; i < position.count; i++) {
    const t = Math.min(1, Math.max(0, -position.getZ(i) / tailLength));
    // Tapers from the base, then fluffs out slightly before a rounded tip.
    const radius = (0.06 - 0.02 * t + 0.016 * Math.sin(Math.PI * Math.max(0, (t - 0.72) / 0.28))) * (t > 0.985 ? 0.4 : 1);
    position.setX(i, position.getX(i) * radius);
    position.setY(i, position.getY(i) * radius);
    const along = t * TAIL_SEGMENTS, bone = Math.min(TAIL_SEGMENTS - 1, Math.floor(along));
    const blend = Math.min(1, along - bone);
    skinIndex.push(bone, Math.min(TAIL_SEGMENTS - 1, bone + 1), 0, 0);
    skinWeight.push(1 - blend, blend, 0, 0);
  }
  tailGeometry.computeVertexNormals();
  tailGeometry.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(skinIndex, 4));
  tailGeometry.setAttribute("skinWeight", new THREE.Float32BufferAttribute(skinWeight, 4));
  for (let index = 0; index < TAIL_SEGMENTS; index++) {
    const bone = new THREE.Bone();
    bone.position.z = index === 0 ? 0 : -TAIL_STEP;
    tail[index - 1]?.add(bone);
    tail.push(bone);
  }
  const skeleton = new THREE.Skeleton(tail);
  const tailRoot = new THREE.Group();
  tailRoot.position.set(0, 0.07, -0.37);
  body.add(tailRoot);
  const tailMesh = new THREE.SkinnedMesh(tailGeometry, fur);
  const tailInk = new THREE.SkinnedMesh(tailGeometry, outline);
  tailMesh.add(tail[0]);
  tailRoot.add(tailMesh, tailInk);
  tailMesh.bind(skeleton);
  tailInk.bind(skeleton, tailMesh.bindMatrix);
  for (const mesh of [tailMesh, tailInk]) mesh.frustumCulled = false;
  const tailTip = new THREE.Mesh(ellipsoid(0.05, [1, 1, 1.3], [0, 0, -0.06]), fur);
  tail[TAIL_SEGMENTS - 1].add(tailTip);

  const dispose = () => {
    const geometries = new Set<THREE.BufferGeometry>();
    const materials = new Set<THREE.Material>();
    root.traverse((object) => {
      if (object instanceof THREE.Mesh || object instanceof THREE.LineSegments) {
        geometries.add(object.geometry);
        for (const material of [object.material].flat()) materials.add(material);
      }
    });
    geometries.forEach((geometry) => geometry.dispose());
    materials.forEach((material) => material.dispose());
    skeleton.dispose();
    root.removeFromParent();
  };

  return { root, body, torso, head, legs, paws, tail, ears, eyes, fur, dispose };
}

export function applyCatPose(model: CatModel, pose: CatPose) {
  model.body.position.set(0, pose.body.y, pose.body.z);
  model.body.rotation.set(-pose.body.pitch, 0, pose.body.roll);
  model.torso.scale.set(1 + pose.body.breathe * 0.6, 1 + pose.body.breathe, 1);
  model.head.position.y = HEAD_Y + pose.head.y;
  model.head.rotation.set(-pose.head.pitch, pose.head.yaw, pose.head.roll, "YXZ");
  for (const name of LEGS) {
    const leg = pose.legs[name];
    model.legs[name].hip.rotation.x = -leg.hip;
    model.legs[name].knee.rotation.x = -leg.knee;
    model.legs[name].paw.rotation.x = -leg.paw;
  }
  pose.tail.forEach((segment, index) => model.tail[index]?.rotation.set(segment.pitch, segment.yaw, 0));
  model.ears.forEach((ear, index) => { ear.rotation.x = -0.12 - pose.ears * (index ? 1.4 : 0.6); });
  for (const eye of model.eyes) {
    eye.group.scale.y = 1 - 0.9 * pose.blink;
    eye.pupil.position.set(pose.pupils.x * 0.014, pose.pupils.y * 0.012, 0);
  }
}
